def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = sum(1 for a in op if a == 'D')

    if opp_def == n:
        return 'D'

    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'D'
    if n == 4:
        return 'D'
    if n == 5:
        return 'C'

    remaining = 100 - n
    if remaining <= 10:
        if opp_def * 3 < n:
            return 'D'
        last_my, last_op = history[-1]
        if last_op == 'C':
            return 'C'
        if n >= 2 and op[-2] == 'C':
            return 'C'
        return 'D'

    opp_r4 = op[3] if n > 3 else 'C'
    retaliator = (opp_r4 == 'D')

    if retaliator and n < 20:
        return 'C'

    recent_op = op[-10:] if n >= 10 else op
    recent_def = sum(1 for a in recent_op if a == 'D')

    if recent_def > 0:
        if op[-1] == 'D':
            return 'C'
        if my[-1] == 'D':
            return 'C'
        if recent_def >= 3:
            return 'D'
        return 'C'

    if not retaliator and opp_def <= n * 0.05:
        if n % 4 == 0:
            return 'D'

    return 'C'
